const ELEMENT_PROP_KEYS = new Set(["theme","fontWeight","dim","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  fontWeight: 400,
  dim: 0.62,
  fontFamily: "Afacad",
  scale: 1,
  delay: 0,
  speed: 1,
};

type StoryDipElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof StoryDipBase>;

const StoryDipInner = forwardRef<
  HTMLDivElement,
  StoryDipElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<StoryDip>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <StoryDipBase
          {...(componentProps as unknown as ComponentProps<typeof StoryDipBase>)}
        />
      </div>
    </Sequence>
  );
});

export const StoryDip = Interactive.withSchema({
  Component: StoryDipInner,
  componentName: "<StoryDip>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
